  Ltac z34_pre :=
    pose proof z34_ff as FF;
    let RSP := fresh "RSP" in pose proof (bv_unsigned_in_range 64 sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
    let ABD := fresh "ABD" in let DAT := fresh "DAT" in
    pose proof (ZB z4s1_dblk D6) as (_ & _ & ABD & DAT & _ & _); unfold ablk, KLS, AIMG_HI in ABD;
    let AT := fresh "AT" in pose proof ATOP_range as AT; unfold ATOP_MIN, ATOP_MAX in AT;
    let TLR := fresh "TLR" in pose proof TOK as (TLR & _); unfold HUF_TABLELOG_MAX in TLR;
    let BL1 := fresh "BL1" in let BL2 := fresh "BL2" in let BL3 := fresh "BL3" in let BL4 := fresh "BL4" in
    let BL5 := fresh "BL5" in let BL6 := fresh "BL6" in
    pose proof (ZB z4s_blocks) as (BL1 & BL2 & BL3 & BL4 & BL5 & BL6); unfold AIMG_HI in *;
    destruct BL5 as [BL5|BL5]; [lia|]; destruct BL6 as [BL6|BL6]; [lia|].
